"application/json": {
"schema": {
"type": "object",
"properties": {
"ok": {
"type": "boolean"
},
"error": {
"type": "string"
},
"products": {
"type": "array",
"items": {
"type": "object",
"properties": {
"product_id": {
"type": "string"
},
"type": {
"type": "string",
"enum": [
"credit_card",
"personal_loan",
"car_loan"
]
},
"card_last4": {
"type": "string",
"description": "credit cards only"
},
"past_due": {
"type": "number"
},
"days_late": {
"type": "integer"
},
"minimum_payment": {
"type": "number",
"description": "credit cards only"
},
"instalment_amount": {
"type": "number",
"description": "loans only"
}
}
}
}
}
}
}
}
},
"500": {
"description": "The service failed. Nothing was recorded. The call may be repeated."
}
}
}
},
