"post": {
"summary": "Record a payment promise. One per product.",
"requestBody": {
"required": true,
"content": {
"application/json": {
"schema": {
"type": "object",
"properties": {
"customer_id": {
"type": "string"
},
"product_id": {
"type": "string"
},
"amount": {
"type": "number"
},
"date": {
"type": "string",
"format": "date"
}
},
"required": [
"customer_id",
"product_id",
"amount",
"date"
]
}
}
}
},
"responses": {
"200": {
"description": "`ok` is false when the action was not carried out.",
"content": {
"application/json": {
"schema": {
"type": "object",
