"post": {
"summary": "Book a callback.",
"requestBody": {
"required": true,
"content": {
"application/json": {
"schema": {
"type": "object",
"properties": {
"customer_id": {
"type": "string"
},
"date": {
"type": "string",
"format": "date"
},
