"post": {
"summary": "Hand the call to a person.",
"requestBody": {
"required": true,
"content": {
"application/json": {
"schema": {
"type": "object",
"properties": {
"customer_id": {
"type": "string"
},
"queue": {
"type": "string",
"enum": [
"restructuring",
"general",
"support"
]
}
},
"required": [
"customer_id",
"queue"
]
}
}
}
},
"responses": {
"200": {
"description": "`ok` is false when the action was not carried out.",
"content": {
"application/json": {
"schema": {
"type": "object",
"properties": {
"ok": {
"type": "boolean"
},
"error": {
"type": "string"
}
}
}
}
}
},
"500": {
"description": "The service failed. Nothing was recorded. The call may be repeated."
}
}
}
},
"/close_call": {
"post": {
"summary": "End the call. Always the last tool call. Nothing is accepted after it.",
"requestBody": {
"required": true,
"content": {
"application/json": {
"schema": {
"type": "object",
"properties": {
"customer_id": {
"type": "string"
},
"outcome": {
"type": "string",
"enum": [
"promise",
"paid",
"transferred",
"no_promise",
"not_verified",
"not_reached"
]
},
"reason": {
"type": "string",
"description": "Required for every outcome except promise and paid. See the table in the brief."
}
},
"required": [
"customer_id",
"outcome"
]
}
}
}
